"""Offline synthetic QUIC v1 receiver trace auditor.

Reads one JSON document on stdin, writes one JSON document on stdout.
All behaviour follows the local finite model described in the task contract.
"""
import json
import re
import sys
from bisect import bisect_right
from operator import itemgetter

MAXOFF = 4611686018427387903
MAXT = 1000000000000
MAX_IDLE = 1000000000
MAX_REQ_BYTES = 16 * 1024 * 1024
MAX_TOTAL_DATA = 2 * 1024 * 1024
MAX_TRACES = 32
MAX_EVENTS = 20000
MAX_PACKETS = 20000
MAX_FRAMES = 60000
MAX_PACKETS_PER_DATAGRAM = 16
MAX_FRAMES_PER_PACKET = 64
MAX_RANGES = 32
INITIAL_MIN = 1200

OUT_INVALID = '{"error":"INVALID_INPUT"}'


class Invalid(Exception):
    __slots__ = ()


# --------------------------------------------------------------------------
# validation helpers
# --------------------------------------------------------------------------

_ID_RE = re.compile(r'\A[A-Za-z0-9_-]{1,32}\Z')
_HEX_RE = re.compile(r'\A(?:[0-9a-f]{2}){0,2048}\Z')

LEVEL_CODES = {'I': 0, 'H': 1, 'Z': 2, 'A': 3}


def _pairs_hook(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise Invalid('duplicate key')
        d[k] = v
    return d


def _bad_number(_x):
    raise Invalid('non integer number')


def _need_dict(o):
    if o.__class__ is not dict:
        raise Invalid('not an object')
    return o


def _need_list(o):
    if o.__class__ is not list:
        raise Invalid('not an array')
    return o


def _keys(o, expected):
    if o.__class__ is not dict:
        raise Invalid('not an object')
    if len(o) != len(expected):
        raise Invalid('key mismatch')
    for k in expected:
        if k not in o:
            raise Invalid('key mismatch')
    return o


def _int(v, lo, hi):
    if v.__class__ is not int:
        raise Invalid('not an integer')
    if v < lo or v > hi:
        raise Invalid('integer out of range')
    return v


def _bool(v):
    if v.__class__ is not bool:
        raise Invalid('not a boolean')
    return v


def _str(v):
    if v.__class__ is not str:
        raise Invalid('not a string')
    return v


def _ranges(v, strict):
    """Validate a RANGES array.  strict=True enforces the CONFIG ordering rules."""
    lst = _need_list(v)
    if len(lst) > MAX_RANGES:
        raise Invalid('too many ranges')
    out = []
    prev_hi = None
    for pair in lst:
        p = _need_list(pair)
        if len(p) != 2:
            raise Invalid('range pair')
        lo = _int(p[0], 0, MAXOFF)
        hi = _int(p[1], 0, MAXOFF)
        if strict:
            if lo > hi:
                raise Invalid('reversed range')
            if prev_hi is not None and lo <= prev_hi + 1:
                raise Invalid('unsorted/overlapping/adjacent range')
            prev_hi = hi
        out.append((lo, hi))
    return tuple(out)


class Cfg(object):
    __slots__ = ('early', 'reject', 'buffer_packets', 'idle_ms', 'max_bidi',
                 'max_uni', 'max_stream_data', 'max_data', 'crypto_limit', 'sent')


_CFG_KEYS = ('early', 'overlap', 'buffer_packets', 'idle_ms', 'max_streams_bidi',
             'max_streams_uni', 'max_stream_data', 'max_data', 'crypto_limit', 'sent')


def _config(o):
    _keys(o, _CFG_KEYS)
    c = Cfg()
    c.early = _bool(o['early'])
    ov = _str(o['overlap'])
    if ov == 'reject':
        c.reject = True
    elif ov == 'first':
        c.reject = False
    else:
        raise Invalid('overlap policy')
    c.buffer_packets = _int(o['buffer_packets'], 0, 1024)
    c.idle_ms = _int(o['idle_ms'], 0, MAX_IDLE)
    c.max_bidi = _int(o['max_streams_bidi'], 0, 1024)
    c.max_uni = _int(o['max_streams_uni'], 0, 1024)
    c.max_stream_data = _int(o['max_stream_data'], 0, 65536)
    c.max_data = _int(o['max_data'], 0, MAXOFF)
    c.crypto_limit = _int(o['crypto_limit'], 0, 65536)
    sent = _keys(o['sent'], ('I', 'H', 'A'))
    c.sent = (_ranges(sent['I'], True), _ranges(sent['H'], True),
              (), _ranges(sent['A'], True))
    return c


# frame type codes
F_PAD, F_PING, F_ACK, F_CRYPTO, F_STREAM, F_RESET, F_STOP, F_CLOSE, F_HD, F_UNK = range(10)

_FRAME_KEYS = {
    'PADDING': ('type',),
    'PING': ('type',),
    'ACK': ('type', 'ranges'),
    'CRYPTO': ('type', 'offset', 'data_hex'),
    'STREAM': ('type', 'id', 'offset', 'data_hex', 'fin'),
    'RESET_STREAM': ('type', 'id', 'final_size'),
    'STOP_SENDING': ('type', 'id'),
    'CLOSE': ('type', 'app', 'code'),
    'HANDSHAKE_DONE': ('type',),
    'UNKNOWN': ('type',),
}


class Counters(object):
    __slots__ = ('events', 'packets', 'frames', 'data')

    def __init__(self):
        self.events = 0
        self.packets = 0
        self.frames = 0
        self.data = 0


def _hexdata(v, cnt):
    s = _str(v)
    if not _HEX_RE.match(s):
        raise Invalid('bad hex')
    b = bytes.fromhex(s)
    cnt.data += len(b)
    if cnt.data > MAX_TOTAL_DATA:
        raise Invalid('too much frame data')
    return b


def _frame(o, cnt):
    _need_dict(o)
    t = o.get('type')
    name = _str(t)
    keys = _FRAME_KEYS.get(name)
    if keys is None:
        raise Invalid('unknown frame name')
    _keys(o, keys)
    cnt.frames += 1
    if cnt.frames > MAX_FRAMES:
        raise Invalid('too many frames')
    if name == 'PADDING':
        return (F_PAD,)
    if name == 'PING':
        return (F_PING,)
    if name == 'ACK':
        return (F_ACK, _ranges(o['ranges'], False))
    if name == 'CRYPTO':
        off = _int(o['offset'], 0, MAXOFF)
        return (F_CRYPTO, off, _hexdata(o['data_hex'], cnt))
    if name == 'STREAM':
        sid = _int(o['id'], 0, MAXOFF)
        off = _int(o['offset'], 0, MAXOFF)
        fin = _bool(o['fin'])
        return (F_STREAM, sid, off, _hexdata(o['data_hex'], cnt), fin)
    if name == 'RESET_STREAM':
        sid = _int(o['id'], 0, MAXOFF)
        fs = _int(o['final_size'], 0, MAXOFF)
        return (F_RESET, sid, fs)
    if name == 'STOP_SENDING':
        return (F_STOP, _int(o['id'], 0, MAXOFF))
    if name == 'CLOSE':
        app = _bool(o['app'])
        code = _int(o['code'], 0, MAXOFF)
        return (F_CLOSE, app, code)
    if name == 'HANDSHAKE_DONE':
        return (F_HD,)
    return (F_UNK,)


def _packet(o, cnt):
    _keys(o, ('level', 'pn', 'auth', 'frames'))
    lvl = LEVEL_CODES.get(_str(o['level']))
    if lvl is None:
        raise Invalid('bad level')
    pn = _int(o['pn'], 0, MAXOFF)
    auth = _bool(o['auth'])
    fr = _need_list(o['frames'])
    if len(fr) > MAX_FRAMES_PER_PACKET:
        raise Invalid('too many frames in packet')
    frames = tuple([_frame(f, cnt) for f in fr])
    cnt.packets += 1
    if cnt.packets > MAX_PACKETS:
        raise Invalid('too many packets')
    return (lvl, pn, auth, frames)


_OP_KEY, _OP_TICK, _OP_DGRAM = 0, 1, 2


def _event(o, cnt):
    _need_dict(o)
    t = _int(o.get('t'), 0, MAXT)
    op = _str(o.get('op'))
    if op == 'key':
        _keys(o, ('t', 'op', 'level', 'action'))
        lvl = LEVEL_CODES.get(_str(o['level']))
        if lvl is None:
            raise Invalid('bad level')
        act = _str(o['action'])
        if act == 'install':
            a = 0
        elif act == 'discard':
            a = 1
        else:
            raise Invalid('bad action')
        cnt.events += 1
        if cnt.events > MAX_EVENTS:
            raise Invalid('too many events')
        return (_OP_KEY, t, lvl, a)
    if op == 'tick':
        _keys(o, ('t', 'op'))
        cnt.events += 1
        if cnt.events > MAX_EVENTS:
            raise Invalid('too many events')
        return (_OP_TICK, t)
    if op == 'datagram':
        _keys(o, ('t', 'op', 'bytes', 'packets'))
        size = _int(o['bytes'], 0, 65535)
        pkts = _need_list(o['packets'])
        n = len(pkts)
        if n < 1 or n > MAX_PACKETS_PER_DATAGRAM:
            raise Invalid('bad packet count')
        plist = tuple([_packet(p, cnt) for p in pkts])
        cnt.events += 1
        if cnt.events > MAX_EVENTS:
            raise Invalid('too many events')
        return (_OP_DGRAM, t, size, plist)
    raise Invalid('bad op')


def _trace(o, ids, cnt):
    _keys(o, ('id', 'config', 'events'))
    tid = _str(o['id'])
    if not _ID_RE.match(tid):
        raise Invalid('bad id')
    if tid in ids:
        raise Invalid('duplicate trace id')
    ids.add(tid)
    cfg = _config(o['config'])
    evs = _need_list(o['events'])
    norm = []
    prev = -1
    for e in evs:
        ev = _event(e, cnt)
        if ev[1] < prev:
            raise Invalid('time not monotonic')
        prev = ev[1]
        norm.append(ev)
    return (tid, cfg, tuple(norm))


def _document(doc, cnt):
    _keys(doc, ('version', 'traces'))
    v = doc['version']
    if v.__class__ is not int or v != 1:
        raise Invalid('bad version')
    traces = _need_list(doc['traces'])
    if len(traces) > MAX_TRACES:
        raise Invalid('too many traces')
    ids = set()
    return [_trace(t, ids, cnt) for t in traces]


# --------------------------------------------------------------------------
# byte storage (sparse interval list of (start, bytes))
# --------------------------------------------------------------------------

_I0 = itemgetter(0)


def _insert_piece(ivs, ps, pb):
    """Insert a piece known not to overlap any existing interval; merge neighbours."""
    k = bisect_right(ivs, ps, key=_I0)
    if k > 0:
        s, b = ivs[k - 1]
        if s + len(b) == ps:
            ps = s
            pb = b + pb
            ivs[k - 1] = (ps, pb)
            k -= 1
            pe = ps + len(pb)
            j = k + 1
            while j < len(ivs):
                s2, b2 = ivs[j]
                if s2 > pe:
                    break
                if s2 == pe:
                    pb = pb + b2
                    pe += len(b2)
                    del ivs[j]
                else:
                    break
            ivs[k] = (ps, pb)
            return
    pe = ps + len(pb)
    j = k
    while j < len(ivs):
        s2, b2 = ivs[j]
        if s2 > pe:
            break
        if s2 == pe:
            pb = pb + b2
            pe += len(b2)
            del ivs[j]
        else:
            break
    ivs.insert(k, (ps, pb))


def store_bytes(ivs, off, data, reject):
    """Store data at off.  Return False when a conflicting byte must be rejected."""
    n = len(data)
    if n == 0:
        return True
    end = off + n
    m = len(ivs)
    j = bisect_right(ivs, off, key=_I0) - 1
    if j < 0:
        j = 0
    pieces = []
    pos = off
    while j < m:
        s, b = ivs[j]
        if s >= end:
            break
        e = s + len(b)
        if e <= off:
            j += 1
            continue
        lo = s if s > off else off
        hi = e if e < end else end
        if b[lo - s:hi - s] != data[lo - off:hi - off]:
            if reject:
                return False
        if lo > pos:
            pieces.append((pos, data[pos - off:lo - off]))
        pos = hi
        j += 1
    if pos < end:
        pieces.append((pos, data[pos - off:]))
    for ps, pb in pieces:
        _insert_piece(ivs, ps, pb)
    return True


def prefix_bytes(ivs):
    if ivs and ivs[0][0] == 0:
        return ivs[0][1]
    return b''


# --------------------------------------------------------------------------
# replay engine
# --------------------------------------------------------------------------

ABSENT, LIVE, DISCARDED = 0, 1, 2
KEY_NAMES = ('absent', 'live', 'discarded')
SPACE = (0, 1, 2, 2)          # level -> packet number space (Z shares Application)
LEVEL_BIT = (1, 2, 4, 8)      # level -> bit
BIT_I, BIT_H, BIT_Z, BIT_A = 1, 2, 4, 8

# allowed level bitmasks per frame type
ALLOW = (
    BIT_I | BIT_H | BIT_Z | BIT_A,   # PADDING
    BIT_I | BIT_H | BIT_Z | BIT_A,   # PING
    BIT_I | BIT_H | BIT_A,           # ACK
    BIT_I | BIT_H | BIT_A,           # CRYPTO
    BIT_Z | BIT_A,                   # STREAM
    BIT_Z | BIT_A,                   # RESET_STREAM
    BIT_Z | BIT_A,                   # STOP_SENDING
    0,                               # CLOSE (handled separately)
    0,                               # HANDSHAKE_DONE
    0,                               # UNKNOWN (handled separately)
)
APP_CLOSE_BIT = BIT_Z | BIT_A


class Stream(object):
    __slots__ = ('highest', 'final_size', 'reset', 'stopped', 'ivs', 'delivered')

    def __init__(self):
        self.highest = 0
        self.final_size = None
        self.reset = False
        self.stopped = False
        self.ivs = []
        self.delivered = bytearray()


class Crypto(object):
    __slots__ = ('highest', 'ivs')

    def __init__(self):
        self.highest = 0
        self.ivs = []


class State(object):
    __slots__ = ('cfg', 'keys', 'pn', 'streams', 'total', 'crypto', 'last_act',
                 'pending', 'inflight', 'inflight_pos', 'terminated', 'term',
                 'records', 'reject', 'idle_ms', 'max_data', 'max_stream_data',
                 'crypto_limit', 'max_bidi', 'max_uni', 'sent', 'buffer_packets')

    def __init__(self, cfg):
        self.cfg = cfg
        self.keys = [LIVE, ABSENT, (LIVE if cfg.early else ABSENT), ABSENT]
        self.pn = [set(), set(), set()]
        self.streams = {}
        self.total = 0
        self.crypto = {0: Crypto(), 1: Crypto(), 3: Crypto()}
        self.last_act = 0
        self.pending = []
        self.inflight = []
        self.inflight_pos = 0
        self.terminated = False
        self.term = None
        self.records = []
        self.reject = cfg.reject
        self.idle_ms = cfg.idle_ms
        self.max_data = cfg.max_data
        self.max_stream_data = cfg.max_stream_data
        self.crypto_limit = cfg.crypto_limit
        self.max_bidi = cfg.max_bidi
        self.max_uni = cfg.max_uni
        self.sent = cfg.sent
        self.buffer_packets = cfg.buffer_packets


def emit(S, ev, pk, status, reason, at, frame):
    S.records.append((ev, pk, status, reason, at, frame))


def terminate(S, state, code, at, src_ev, src_pk, src_fr, peer_code):
    if S.terminated:
        return
    S.terminated = True
    S.term = (state, code, at, (src_ev, src_pk, src_fr), peer_code)
    for e in S.pending:
        emit(S, e[1], e[2], 'dropped', 'CONNECTION_CLOSED', at, None)
    S.pending = []
    infl = S.inflight
    for e in infl[S.inflight_pos:]:
        emit(S, e[1], e[2], 'dropped', 'CONNECTION_CLOSED', at, None)
    S.inflight = []
    S.inflight_pos = 0


def rollback(S, undo, total_snap):
    for u in reversed(undo):
        k = u[0]
        if k == 0:
            del S.streams[u[1]]
        elif k == 1:
            st = S.streams[u[1]]
            st.highest = u[2]
            st.final_size = u[3]
            st.reset = u[4]
            st.stopped = u[5]
            st.ivs = u[6]
            d = st.delivered
            if len(d) > u[7]:
                del d[u[7]:]
        else:
            cs = S.crypto[u[1]]
            cs.highest = u[2]
            cs.ivs = u[3]
    S.total = total_snap


def get_stream(S, sid, undo, touched):
    st = S.streams.get(sid)
    if st is None:
        st = Stream()
        S.streams[sid] = st
        undo.append((0, sid))
    elif sid not in touched:
        touched.add(sid)
        undo.append((1, sid, st.highest, st.final_size, st.reset, st.stopped,
                     list(st.ivs), len(st.delivered)))
    return st


def get_crypto(S, level, undo, touched):
    cs = S.crypto[level]
    if level not in touched:
        touched.add(level)
        undo.append((2, level, cs.highest, list(cs.ivs)))
    return cs


def do_stream(S, f, undo, touched):
    sid = f[1]
    d = sid & 3
    if d == 1 or d == 3:
        return 'STREAM_STATE_ERROR'
    if (sid >> 2) + 1 > (S.max_bidi if d == 0 else S.max_uni):
        return 'STREAM_LIMIT_ERROR'
    off = f[2]
    data = f[3]
    fin = f[4]
    end = off + len(data)
    if end > MAXOFF:
        return 'FRAME_ENCODING_ERROR'
    st = get_stream(S, sid, undo, touched)
    fs = st.final_size
    if fs is not None:
        if end > fs or (fin and end != fs):
            return 'FINAL_SIZE_ERROR'
    h = st.highest
    if fin and end < h:
        return 'FINAL_SIZE_ERROR'
    if end > S.max_stream_data:
        return 'FLOW_CONTROL_ERROR'
    nh = h if h > end else end
    if S.total - h + nh > S.max_data:
        return 'FLOW_CONTROL_ERROR'
    if not st.reset:
        if not store_bytes(st.ivs, off, data, S.reject):
            return 'PROTOCOL_VIOLATION'
        if nh != h:
            S.total += nh - h
            st.highest = nh
        if fin:
            st.final_size = end
        ivs = st.ivs
        if ivs and ivs[0][0] == 0:
            dl = len(st.delivered)
            chunk = ivs[0][1]
            if len(chunk) > dl:
                st.delivered += chunk[dl:]
    else:
        if nh != h:
            S.total += nh - h
            st.highest = nh
        if fin:
            st.final_size = end
    return None


def do_reset(S, f, undo, touched):
    sid = f[1]
    d = sid & 3
    if d == 1 or d == 3:
        return 'STREAM_STATE_ERROR'
    if (sid >> 2) + 1 > (S.max_bidi if d == 0 else S.max_uni):
        return 'STREAM_LIMIT_ERROR'
    fsz = f[2]
    st = get_stream(S, sid, undo, touched)
    if st.final_size is not None and fsz != st.final_size:
        return 'FINAL_SIZE_ERROR'
    h = st.highest
    if fsz < h:
        return 'FINAL_SIZE_ERROR'
    if fsz > S.max_stream_data:
        return 'FLOW_CONTROL_ERROR'
    nh = h if h > fsz else fsz
    if S.total - h + nh > S.max_data:
        return 'FLOW_CONTROL_ERROR'
    if nh != h:
        S.total += nh - h
        st.highest = nh
    st.final_size = fsz
    st.reset = True
    return None


def do_stop(S, f, undo, touched):
    sid = f[1]
    if (sid & 3) != 0:
        return 'STREAM_STATE_ERROR'
    if (sid >> 2) + 1 > S.max_bidi:
        return 'STREAM_LIMIT_ERROR'
    st = get_stream(S, sid, undo, touched)
    st.stopped = True
    return None


def do_crypto(S, level, f, undo, touched):
    off = f[1]
    data = f[2]
    end = off + len(data)
    if end > MAXOFF:
        return 'FRAME_ENCODING_ERROR'
    if end > S.crypto_limit:
        return 'CRYPTO_BUFFER_EXCEEDED'
    cs = get_crypto(S, level, undo, touched)
    if not store_bytes(cs.ivs, off, data, S.reject):
        return 'PROTOCOL_VIOLATION'
    if end > cs.highest:
        cs.highest = end
    return None


def do_ack(S, level, ranges):
    if not ranges:
        return 'FRAME_ENCODING_ERROR'
    prev = None
    for lo, hi in ranges:
        if lo > hi:
            return 'FRAME_ENCODING_ERROR'
        if prev is not None and lo <= prev + 1:
            return 'FRAME_ENCODING_ERROR'
        prev = hi
    sent = S.sent[level]
    n = len(sent)
    j = 0
    for lo, hi in ranges:
        while j < n and sent[j][1] < lo:
            j += 1
        cur = lo
        k = j
        while cur <= hi:
            if k >= n:
                return 'PROTOCOL_VIOLATION'
            s_lo, s_hi = sent[k]
            if s_lo > cur:
                return 'PROTOCOL_VIOLATION'
            cur = s_hi + 1
            k += 1
    return None


def fail_packet(S, ev, pk, code, fidx, at, undo, total_snap):
    if undo:
        rollback(S, undo, total_snap)
    else:
        S.total = total_snap
    emit(S, ev, pk, 'error', code, at, fidx)
    terminate(S, 'closed', code, at, ev, pk, fidx, None)


def handle_packet(S, ev, pk, pkt, at):
    lvl, pn, auth, frames = pkt
    if S.terminated:
        emit(S, ev, pk, 'dropped', 'CONNECTION_CLOSED', at, None)
        return
    if not auth:
        emit(S, ev, pk, 'dropped', 'AUTH', at, None)
        return
    sp = SPACE[lvl]
    if pn in S.pn[sp]:
        emit(S, ev, pk, 'duplicate', 'DUPLICATE', at, None)
        return
    n = len(frames)
    if n == 0:
        emit(S, ev, pk, 'error', 'FRAME_ENCODING_ERROR', at, None)
        terminate(S, 'closed', 'FRAME_ENCODING_ERROR', at, ev, pk, None, None)
        return
    bit = LEVEL_BIT[lvl]
    for i in range(n):
        ft = frames[i][0]
        if ft == F_UNK:
            emit(S, ev, pk, 'error', 'FRAME_ENCODING_ERROR', at, i)
            terminate(S, 'closed', 'FRAME_ENCODING_ERROR', at, ev, pk, i, None)
            return
        if ft == F_CLOSE:
            if frames[i][1] and not (bit & APP_CLOSE_BIT):
                emit(S, ev, pk, 'error', 'PROTOCOL_VIOLATION', at, i)
                terminate(S, 'closed', 'PROTOCOL_VIOLATION', at, ev, pk, i, None)
                return
        elif not (ALLOW[ft] & bit):
            emit(S, ev, pk, 'error', 'PROTOCOL_VIOLATION', at, i)
            terminate(S, 'closed', 'PROTOCOL_VIOLATION', at, ev, pk, i, None)
            return

    undo = []
    touched = set()
    total_snap = S.total
    close_frame = -1
    close_app = False
    close_code = 0
    for i in range(n):
        f = frames[i]
        ft = f[0]
        if ft == F_STREAM:
            err = do_stream(S, f, undo, touched)
        elif ft == F_CRYPTO:
            err = do_crypto(S, lvl, f, undo, touched)
        elif ft == F_ACK:
            err = do_ack(S, lvl, f[1])
        elif ft == F_RESET:
            err = do_reset(S, f, undo, touched)
        elif ft == F_STOP:
            err = do_stop(S, f, undo, touched)
        elif ft == F_CLOSE:
            close_frame = i
            close_app = f[1]
            close_code = f[2]
            break
        else:
            err = None
        if err is not None:
            fail_packet(S, ev, pk, err, i, at, undo, total_snap)
            return
    # commit
    S.pn[sp].add(pn)
    S.last_act = at
    emit(S, ev, pk, 'accepted', 'OK', at, None)
    if close_frame >= 0:
        code = 'PEER_APPLICATION_CLOSE' if close_app else 'PEER_TRANSPORT_CLOSE'
        terminate(S, 'closed', code, at, ev, pk, close_frame, close_code)


def drain(S, level, at):
    sel = [e for e in S.pending if e[3] == level]
    if not sel:
        return
    S.pending = [e for e in S.pending if e[3] != level]
    S.inflight = sel
    S.inflight_pos = 0
    for i in range(len(sel)):
        if S.terminated:
            break
        S.inflight_pos = i + 1
        e = sel[i]
        handle_packet(S, e[1], e[2], e[4], at)
    S.inflight = []
    S.inflight_pos = 0


def run_trace(tid, cfg, events):
    S = State(cfg)
    early = cfg.early
    idle_ms = cfg.idle_ms
    for ev in range(len(events)):
        e = events[ev]
        op = e[0]
        t = e[1]
        if not S.terminated and idle_ms and t >= S.last_act + idle_ms:
            deadline = S.last_act + idle_ms
            terminate(S, 'idle', 'IDLE_TIMEOUT', deadline, ev, None, None, None)
        if S.terminated:
            if op == _OP_DGRAM:
                for pk in range(len(e[3])):
                    emit(S, ev, pk, 'dropped', 'CONNECTION_CLOSED', t, None)
            continue
        if op == _OP_DGRAM:
            size = e[2]
            pkts = e[3]
            last = len(pkts) - 1
            layout = False
            for i in range(last):
                if pkts[i][0] == 3:
                    layout = True
                    break
            if layout:
                for i in range(len(pkts)):
                    emit(S, ev, i, 'dropped', 'LAYOUT', t, None)
                continue
            for i in range(len(pkts)):
                pkt = pkts[i]
                lvl = pkt[0]
                if S.terminated:
                    emit(S, ev, i, 'dropped', 'CONNECTION_CLOSED', t, None)
                    continue
                if lvl == 0 and size < INITIAL_MIN:
                    emit(S, ev, i, 'dropped', 'INITIAL_TOO_SMALL', t, None)
                    continue
                if lvl == 2 and not early:
                    emit(S, ev, i, 'dropped', 'EARLY_REJECTED', t, None)
                    continue
                ks = S.keys[lvl]
                if ks == DISCARDED:
                    emit(S, ev, i, 'dropped', 'KEYS_DISCARDED', t, None)
                    continue
                if ks == ABSENT:
                    if len(S.pending) < S.buffer_packets:
                        S.pending.append((t, ev, i, lvl, pkt))
                    else:
                        emit(S, ev, i, 'dropped', 'BUFFER_FULL', t, None)
                    continue
                handle_packet(S, ev, i, pkt, t)
        elif op == _OP_KEY:
            lvl = e[2]
            if e[3] == 1:      # discard
                if S.keys[lvl] != DISCARDED:
                    S.keys[lvl] = DISCARDED
                    pend = S.pending
                    if pend:
                        keep = []
                        for q in pend:
                            if q[3] == lvl:
                                emit(S, q[1], q[2], 'dropped', 'KEYS_DISCARDED', t, None)
                            else:
                                keep.append(q)
                        S.pending = keep
            else:              # install
                if S.keys[lvl] == ABSENT:
                    S.keys[lvl] = LIVE
                    drain(S, lvl, t)
        # tick: nothing else to do
    for q in S.pending:
        emit(S, q[1], q[2], 'buffered', 'NO_KEYS', q[0], None)
    S.pending = []

    recs = sorted(S.records, key=lambda r: (r[0], r[1]))
    packets = [{'event': r[0], 'packet': r[1], 'status': r[2], 'reason': r[3],
                'at_ms': r[4], 'frame': r[5]} for r in recs]

    if S.terminated:
        state, code, at, src, peer = S.term
        conn = {'state': state, 'code': code, 'at_ms': at,
                'source': {'event': src[0], 'packet': src[1], 'frame': src[2]},
                'peer_code': peer, 'last_activity_ms': S.last_act}
    else:
        conn = {'state': 'open', 'code': None, 'at_ms': None, 'source': None,
                'peer_code': None, 'last_activity_ms': S.last_act}

    streams = []
    for sid in sorted(S.streams):
        st = S.streams[sid]
        streams.append({'id': sid, 'highest': st.highest, 'final_size': st.final_size,
                        'reset': st.reset, 'stopped': st.stopped,
                        'delivered_hex': bytes(st.delivered).hex()})
    crypto = []
    for lvl in (0, 1, 3):
        cs = S.crypto[lvl]
        crypto.append({'level': 'IHA'[lvl] if lvl != 3 else 'A',
                       'highest': cs.highest,
                       'contiguous_hex': prefix_bytes(cs.ivs).hex()})
    return {'id': tid, 'packets': packets, 'connection': conn,
            'keys': {'I': KEY_NAMES[S.keys[0]], 'H': KEY_NAMES[S.keys[1]],
                     'Z': KEY_NAMES[S.keys[2]], 'A': KEY_NAMES[S.keys[3]]},
            'received_total': S.total, 'streams': streams, 'crypto': crypto}


CRYPTO_LEVEL_NAMES = ('I', 'H', 'Z', 'A')


def main(argv):
    raw = sys.stdin.buffer.read()
    if len(raw) > MAX_REQ_BYTES:
        sys.stdout.write(OUT_INVALID)
        return 0
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        sys.stdout.write(OUT_INVALID)
        return 0
    try:
        doc = json.loads(text, object_pairs_hook=_pairs_hook,
                         parse_float=_bad_number, parse_constant=_bad_number)
        cnt = Counters()
        traces = _document(doc, cnt)
        results = [run_trace(t[0], t[1], t[2]) for t in traces]
        out = json.dumps({'version': 1, 'results': results}, separators=(',', ':'))
    except Invalid:
        sys.stdout.write(OUT_INVALID)
        return 0
    except RecursionError:
        sys.stdout.write(OUT_INVALID)
        return 0
    except Exception:
        sys.stdout.write(OUT_INVALID)
        return 0
    sys.stdout.write(out)
    return 0


if __name__ == '__main__':
    try:
        rc = main(sys.argv)
    except BaseException:
        try:
            sys.stdout.write(OUT_INVALID)
        except Exception:
            pass
        rc = 0
    sys.stdout.flush()
    sys.exit(rc)
