from harness import *

def naive(frames, reject, limit, is_crypto):
    """frames: list of (offset, bytes). Returns (None, highest, prefixhex) or (idx, code, None)."""
    data = {}
    highest = 0
    for i, (off, b) in enumerate(frames):
        end = off + len(b)
        if end > limit:
            return (i, 'CRYPTO_BUFFER_EXCEEDED' if is_crypto else 'FLOW_CONTROL_ERROR', None)
        for k in range(len(b)):
            o = off + k
            if o in data and data[o] != b[k] and reject:
                return (i, 'PROTOCOL_VIOLATION', None)
        for k in range(len(b)):
            o = off + k
            if o not in data:
                data[o] = b[k]
        highest = max(highest, end)
    p = 0
    while p in data:
        p += 1
    return (None, highest, bytes(data[i] for i in range(p)).hex())

