from harness import *

MAXOFF = 4611686018427387903

def rand_ranges(rng, strict, n=None):
    n = rng.randint(0, 4) if n is None else n
    out = []
    cur = rng.randint(0, 50)
    for _ in range(n):
        lo = cur
        hi = lo + rng.randint(0, 5)
        out.append([lo, hi])
        cur = hi + (rng.randint(2, 6) if strict else rng.randint(-2, 6))
        cur = max(0, cur)
    return out

def rand_frame(rng, level):
    kinds = ['PADDING','PING','ACK','CRYPTO','STREAM','RESET_STREAM','STOP_SENDING','CLOSE','HANDSHAKE_DONE','UNKNOWN']
    k = rng.choice(kinds)
    if k == 'ACK':
        return {"type":"ACK","ranges":rand_ranges(rng, False)}
    if k == 'CRYPTO':
        return {"type":"CRYPTO","offset":rng.choice([0,1,2,5,17,63,64,MAXOFF-1,MAXOFF]),
                "data_hex":bytes(rng.randrange(256) for _ in range(rng.randint(0,6))).hex()}
    if k == 'STREAM':
        return {"type":"STREAM","id":rng.choice([0,1,2,3,4,6,8,9,12,4096,MAXOFF]),
                "offset":rng.choice([0,1,2,5,17,63,64,65535,MAXOFF-1,MAXOFF]),
                "data_hex":bytes(rng.randrange(256) for _ in range(rng.randint(0,6))).hex(),
                "fin":rng.random()<0.3}
    if k == 'RESET_STREAM':
        return {"type":"RESET_STREAM","id":rng.choice([0,1,2,3,4,8,12]),"final_size":rng.choice([0,1,5,64,65536,MAXOFF])}
    if k == 'STOP_SENDING':
        return {"type":"STOP_SENDING","id":rng.choice([0,1,2,3,4,8,12])}
    if k == 'CLOSE':
        return {"type":"CLOSE","app":rng.random()<0.5,"code":rng.choice([0,1,7,MAXOFF])}
    return {"type":k}

def rand_packet(rng, last):
    level = rng.choice(['I','H','Z','A'] if last else ['I','H','Z'])
    nf = rng.randint(0, 4)
