CODES = ALLOWED['error'] | {'IDLE_TIMEOUT','PEER_APPLICATION_CLOSE','PEER_TRANSPORT_CLOSE'}

def invariants(doc, res, problems):
    assert set(res.keys()) == {'version','results'}, res.keys()
    assert res['version'] == 1
    assert len(res['results']) == len(doc['traces'])
    for tr, r in zip(doc['traces'], res['results']):
        assert set(r.keys()) == {'id','packets','connection','keys','received_total','streams','crypto'}, r.keys()
        assert r['id'] == tr['id']
        want = []
        for ei, ev in enumerate(tr['events']):
            if ev['op'] == 'datagram':
                for pi in range(len(ev['packets'])):
                    want.append((ei, pi))
        got = [(p['event'], p['packet']) for p in r['packets']]
        if got != want:
            problems.append('packet record set/order %s != %s' % (got, want))
        term_idx = None
        for i, p in enumerate(r['packets']):
            assert set(p.keys()) == {'event','packet','status','reason','at_ms','frame'}, p.keys()
            if p['status'] not in ALLOWED: problems.append('bad status %r' % p['status'])
            elif p['reason'] not in ALLOWED[p['status']]: problems.append('bad reason %r for %r' % (p['reason'], p['status']))
            if p['status'] == 'error' and p['reason'] not in ALLOWED['error']: problems.append('bad err code')
            if p['status'] != 'error' and p['frame'] is not None: problems.append('frame non-null for %s' % p['status'])
            if p['frame'] is not None:
                fr = tr['events'][p['event']]['packets'][p['packet']]['frames']
                if not (0 <= p['frame'] < len(fr)): problems.append('frame idx out of range')
            if term_idx is not None and i > term_idx:
                if not (p['status'] == 'dropped' and p['reason'] == 'CONNECTION_CLOSED'):
                    problems.append('record after termination not CONNECTION_CLOSED: %r' % (p,))
            if p['status'] == 'error':
                term_idx = i
            if p['status'] == 'accepted':
                fr = tr['events'][p['event']]['packets'][p['packet']]['frames']
                if any(f['type'] == 'CLOSE' for f in fr):
                    term_idx = i
        c = r['connection']
        assert set(c.keys()) == {'state','code','at_ms','source','peer_code','last_activity_ms'}
        if c['state'] == 'open':
            if not (c['code'] is None and c['at_ms'] is None and c['source'] is None and c['peer_code'] is None):
                problems.append('open conn has non-null fields')
            if any(p['status'] == 'dropped' and p['reason'] == 'CONNECTION_CLOSED' for p in r['packets']):
                problems.append('CONNECTION_CLOSED while open')
        else:
            if c['state'] not in ('closed','idle'): problems.append('bad state')
            if c['code'] not in CODES: problems.append('bad code %r' % c['code'])
            if not isinstance(c['at_ms'], int): problems.append('bad at_ms')
            s = c['source']
            if s is None or set(s.keys()) != {'event','packet','frame'}: problems.append('bad source %r' % (s,))
            if (c['code'] == 'PEER_APPLICATION_CLOSE') != (c['peer_code'] is not None):
                problems.append('peer_code mismatch %r' % (c,))
            if (c['state'] == 'idle') != (c['code'] == 'IDLE_TIMEOUT'): problems.append('idle/code mismatch')
            if any(p['status'] == 'buffered' for p in r['packets']): problems.append('buffered after termination')
        assert set(r['keys'].keys()) == {'I','H','Z','A'}
        for v in r['keys'].values():
            if v not in ('absent','live','discarded'): problems.append('bad key state %r' % v)
        tot = 0
        ids = []
        for s in r['streams']:
            assert set(s.keys()) == {'id','highest','final_size','reset','stopped','delivered_hex'}, s.keys()
            ids.append(s['id'])
            tot += s['highest']
            if len(s['delivered_hex']) // 2 > s['highest']: problems.append('delivered > highest')
            if s['final_size'] is not None and s['highest'] > s['final_size']: problems.append('highest > final_size')
        if ids != sorted(ids): problems.append('streams unsorted')
        if len(set(ids)) != len(ids): problems.append('duplicate stream ids')
        if tot != r['received_total']: problems.append('total mismatch %d != %d' % (tot, r['received_total']))
        lv = [x['level'] for x in r['crypto']]
        if lv != ['I','H','A']: problems.append('crypto levels %r' % lv)
        for x in r['crypto']:
            assert set(x.keys()) == {'level','highest','contiguous_hex'}
            if len(x['contiguous_hex'])//2 > x['highest']: problems.append('crypto contiguous > highest')
        # last activity
        la = c['last_activity_ms']
        acc = [p['at_ms'] for p in r['packets'] if p['status'] == 'accepted']
        if acc and la != max(acc): problems.append('last_activity %r != %r' % (la, max(acc)))
        if not acc and la != 0: problems.append('last_activity should be 0')

