NUMKEYS = {'t','pn','bytes','offset','id','final_size','code','buffer_packets','idle_ms',
           'max_streams_bidi','max_streams_uni','max_stream_data','max_data','crypto_limit','version'}
STRKEYS = {'op','level','action','overlap','type','data_hex'}
BOOLKEYS = {'auth','fin','app','early'}
OBJKEYS = {'ranges','frames','packets','events','traces','sent','config'}

def mutate(rng, doc):
    """Return a mutated doc that MUST be invalid."""
    kind = rng.randint(0, 6)
    d = copy.deepcopy(doc)
    objs = []
    def walk(o, path):
        if isinstance(o, dict):
            objs.append((o, path))
            for k, v in o.items(): walk(v, path + [k])
        elif isinstance(o, list):
            for i, v in enumerate(o): walk(v, path + [i])
    walk(d, [])
    dicts = [o for o in objs if o[0]]
    if not dicts:
        return {"version":1,"traces":[],"zz":1}
    if kind == 0:   # numeric -> -1
        cand = [(o,k) for o,_ in dicts for k in o if k in NUMKEYS]
        if not cand: return None
        o,k = rng.choice(cand); o[k] = -1
    elif kind == 1: # string -> bogus
        cand = [(o,k) for o,_ in dicts for k in o if k in STRKEYS]
        if not cand: return None
        o,k = rng.choice(cand); o[k] = "\u0000zz"
    elif kind == 2: # bool -> 1
        cand = [(o,k) for o,_ in dicts for k in o if k in BOOLKEYS]
        if not cand: return None
        o,k = rng.choice(cand); o[k] = 1
    elif kind == 3: # container -> 5
        cand = [(o,k) for o,_ in dicts for k in o if k in OBJKEYS]
        if not cand: return None
        o,k = rng.choice(cand); o[k] = 5
    elif kind == 4: # delete a key
        o,_ = rng.choice(dicts)
        if not o: return None
        del o[rng.choice(list(o.keys()))]
    elif kind == 5: # add unknown key
        o,_ = rng.choice(dicts); o['zzz_unknown'] = 1
    else:           # wrong type: int -> string
        cand = [(o,k) for o,_ in dicts for k in o if k in NUMKEYS]
        if not cand: return None
        o,k = rng.choice(cand); o[k] = "3"
    return d

def mutate_struct(rng, doc):
    d = copy.deepcopy(doc)
    if not d['traces']: return None
    tr = rng.choice(d['traces'])
    k = rng.randint(0, 5)
