import sys, json, random, copy
sys.path.insert(0, '/workspace/tmp/t')
from harness import *
import ref

def to_ref(doc):
    """decode hex strings into bytes for the reference model"""
    d = copy.deepcopy(doc)
    for tr in d['traces']:
        for e in tr['events']:
            if e['op'] == 'datagram':
                for p in e['packets']:
                    for f in p['frames']:
                        if 'data_hex' in f:
                            f['data'] = bytes.fromhex(f.pop('data_hex'))
                        if 'ranges' in f:
                            f['ranges'] = [tuple(x) for x in f['ranges']]
        for k in ('I','H','A'):
            tr['config']['sent'][k] = [tuple(x) for x in tr['config']['sent'][k]]
    return d

def norm(x):
    return json.loads(json.dumps(x, sort_keys=True))

import fuzz as F

rng = random.Random(int(sys.argv[2]) if len(sys.argv) > 2 else 5)
N = int(sys.argv[1]) if len(sys.argv) > 1 else 200
bad = 0
for it in range(N):
    doc = F.rand_doc(rng)
    got, _ = run(doc)
    if got == INVALID:
        print('iter', it, 'valid doc rejected!'); print(json.dumps(doc)[:2000]); bad += 1; break
    rd = to_ref(doc)
    want = {'version': 1, 'results': [ref.run_trace(t['id'], t['config'], t['events']) for t in rd['traces']]}
    if norm(got) != norm(want):
        bad += 1
        print('MISMATCH iter', it)
        for i, (a, b) in enumerate(zip(got['results'], want['results'])):
            if norm(a) != norm(b):
                print('trace', i, a['id'])
                for k in a:
                    if norm(a[k]) != norm(b[k]):
                        print('  key', k)
                        print('   got :', json.dumps(a[k])[:1500])
                        print('   want:', json.dumps(b[k])[:1500])
        json.dump(doc, open('/workspace/tmp/t/reffail.json','w'))
        if bad > 2: break
print('done iters', it + 1, 'bad', bad)
