"""Friendly generator: mostly-valid traffic that reaches deep state."""
import random
MAXOFF = 4611686018427387903

def rand_sent(rng):
    out = []
    cur = 0
    for _ in range(rng.randint(1, 4)):
        lo = cur + rng.randint(0, 3)
        hi = lo + rng.randint(0, 4)
        out.append([lo, hi])
        cur = hi + 2
    return out

def rand_frame(rng, level, cfg):
    r = rng.random()
    if r < 0.15:
        return {"type": "PADDING"} if rng.random() < 0.5 else {"type": "PING"}
    if level in ('I', 'H', 'A') and r < 0.3:
        rs = []
        for lo, hi in cfg['sent'][level][:2]:
            a = lo + rng.randint(0, max(0, hi - lo))
            b = hi - rng.randint(0, max(0, hi - a))
            if a <= b:
                rs.append([a, b])
        if not rs:
            rs = [[cfg['sent'][level][0][0], cfg['sent'][level][0][0]]]
        return {"type": "ACK", "ranges": rs}
    if level in ('I', 'H', 'A') and r < 0.45:
        lim = cfg['crypto_limit']
        off = rng.randint(0, max(0, lim - 1))
        ln = min(rng.randint(0, 4), lim - off)
        return {"type": "CRYPTO", "offset": off,
                "data_hex": bytes(rng.randrange(4) for _ in range(ln)).hex()}
    if level in ('Z', 'A'):
        k = rng.random()
        if k < 0.7:
            bidi = rng.random() < 0.5
            n = rng.randint(0, min(3, (cfg['max_streams_bidi'] if bidi else cfg['max_streams_uni']) - 1))
            if n < 0:
                return {"type": "PING"}
            sid = n * 4 + (0 if bidi else 2)
            msd = cfg['max_stream_data']
            off = rng.randint(0, max(0, msd - 1))
            ln = min(rng.randint(0, 5), msd - off)
            return {"type": "STREAM", "id": sid, "offset": off,
                    "data_hex": bytes(rng.randrange(4) for _ in range(ln)).hex(),
                    "fin": rng.random() < 0.25}
        if k < 0.85:
            n = rng.randint(0, max(0, cfg['max_streams_bidi'] - 1))
            return {"type": "STOP_SENDING", "id": n * 4}
        n = rng.randint(0, max(0, min(cfg['max_streams_bidi'], cfg['max_streams_uni']) - 1))
        bidi = rng.random() < 0.5
        sid = n * 4 + (0 if bidi else 2)
        return {"type": "RESET_STREAM", "id": sid, "final_size": rng.randint(0, cfg['max_stream_data'])}
    return {"type": "PING"}

def rand_trace(rng, idx):
    cfg = {"early": rng.random() < 0.5,
           "overlap": rng.choice(['reject', 'first']),
           "buffer_packets": rng.choice([0, 1, 2, 8, 1024]),
           "idle_ms": rng.choice([0, 0, 20, 100, 100000]),
           "max_streams_bidi": rng.choice([1, 2, 4, 8]),
           "max_streams_uni": rng.choice([1, 2, 4, 8]),
           "max_stream_data": rng.choice([8, 32, 64, 65536]),
           "max_data": rng.choice([16, 64, 1000, MAXOFF]),
           "crypto_limit": rng.choice([8, 32, 64, 65536]),
           "sent": {"I": rand_sent(rng), "H": rand_sent(rng), "A": rand_sent(rng)}}
    evs = []
    t = 0
    # some key installs first
    for lv in ('H', 'A', 'Z'):
        if rng.random() < 0.6:
            evs.append({"t": t, "op": "key", "level": lv, "action": "install"})
            t += rng.choice([0, 1])
    pn = {'I': 0, 'H': 0, 'Z': 0, 'A': 0}
    for i in range(rng.randint(1, 14)):
        t += rng.choice([0, 1, 2, 5, 17])
        r = rng.random()
        if r < 0.12:
            evs.append({"t": t, "op": "key", "level": rng.choice(['I', 'H', 'Z', 'A']),
                        "action": rng.choice(['install', 'discard'])})
            continue
        if r < 0.2:
            evs.append({"t": t, "op": "tick"})
            continue
        n = rng.randint(1, 5)
        pkts = []
